const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Mount Etna is in CET (UTC+1). 1:37 am on Feb 23 is 00:37 UTC on Feb 23.
  // The Aqua satellite (MYD collections) has a ~1:30 am/pm local overpass time, making it ideal.
  const etnaSummit = ee.Geometry.Point([14.995, 37.751]);
  const startDate = '2021-02-23';
  const endDate = '2021-02-24'; // Single day filter

  // Define a polygon west of the summit to test the hypothesis.
  const westPolygon = ee.Geometry.Polygon([[
    [14.99, 37.78], [14.80, 37.78],
    [14.80, 37.72], [14.99, 37.72]
  ]]);

  // Define a reference polygon on the eastern side for comparison.
  const eastPolygon = ee.Geometry.Polygon([[
    [15.00, 37.78], [15.20, 37.78],
    [15.20, 37.72], [15.00, 37.72]
  ]]);

  // 2. Data Acquisition & Check
  // Use MODIS Aqua Land Surface Temperature for nighttime thermal analysis.
  const collection = ee.ImageCollection('MODIS/061/MYD11A1')
    .filterDate(startDate, endDate)
    .filterBounds(etnaSummit);

  const imageCount = collection.size().getInfo();
  if (imageCount === 0) {
    console.log('No MODIS Aqua images found for the specified date.');
    console.log('A: No'); // No plume visible means it did not go west.
    return;
  }

  const image = collection.first();
  // LST_Night_1km band is in Kelvin. Scale factor is 0.02.
  const lst = image.select('LST_Night_1km').multiply(0.02);
  const lstCelsius = lst.subtract(273.15); // Convert to Celsius

  // 3. Processing & Calculation
  // Calculate the average temperature in both the western and eastern polygons.
  const scale = 1000; // MODIS LST is 1km resolution

  const westMeanResult = lstCelsius.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: westPolygon,
    scale: scale,
    maxPixels: 1e9
  }).get('LST_Night_1km');

  const eastMeanResult = lstCelsius.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: eastPolygon,
    scale: scale,
    maxPixels: 1e9
  }).get('LST_Night_1km');

  // Also get pixel counts to ensure validity
  const westCount = lstCelsius.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: westPolygon,
    scale: scale,
    maxPixels: 1e9
  }).get('LST_Night_1km').getInfo();

  const eastCount = lstCelsius.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: eastPolygon,
    scale: scale,
    maxPixels: 1e9
  }).get('LST_Night_1km').getInfo();

  if (westCount === 0 || eastCount === 0) {
      console.log(`West Valid Pixels: ${westCount}`);
      console.log(`East Valid Pixels: ${eastCount}`);
      console.log('C2');
      return;
  }

  const westMean = westMeanResult.getInfo();
  const eastMean = eastMeanResult.getInfo();

  // 4. Validation & Final Answer
  if (westMean === null || eastMean === null) {
    console.log('Calculation failed: Mean temperature could not be computed.');
    console.log('C3');
    return;
  }

  // A warm plume would elevate the temperature compared to a clear area.
  const plumeEvidenceThreshold = 1.0; // Plume is at least 1°C warmer than the other side.
  const temperatureDifference = eastMean - westMean;

  console.log(`Image Count: ${imageCount}`);
  console.log(`Valid Pixels (West): ${westCount}`);
  console.log(`Valid Pixels (East): ${eastCount}`);
  console.log(`Mean Night Temp West (°C): ${westMean.toFixed(2)}`);
  console.log(`Mean Night Temp East (°C): ${eastMean.toFixed(2)}`);
  console.log(`Difference (East - West) (°C): ${temperatureDifference.toFixed(2)}`);

  // If the eastern side is significantly warmer, the plume went east.
  // If there's no significant difference, we can't confirm a westward plume.
  if (temperatureDifference > plumeEvidenceThreshold) {
    console.log('Evidence suggests plume moved east, not west.');
    console.log('B');
  } else {
    console.log('No thermal evidence of a significant plume on the western side.');
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
  console.error(e);
  console.log('D');
});
